//! The third-party licences shipped in the binaries: `licenses/THIRD-PARTY-LICENSES.txt`
//! (generated by `cargo xtask licenses`, see `crates/xtask/src/licenses.rs`) is embedded
//! here; the apps show the part of it that is compiled into them on this platform — the
//! summary in Help ▸ About, the whole list in Third-Party Licences… / `gitty --licenses`.

use std::collections::{BTreeMap, BTreeSet};
use std::fmt::Write as _;

/// The generated list for both apps and all platforms.
pub const LIST: &str = include_str!("../../../licenses/THIRD-PARTY-LICENSES.txt");

/// The list's path in the source repository (where release packages also have it).
pub const LIST_PATH: &str = "licenses/THIRD-PARTY-LICENSES.txt";

const COMPONENTS: &str = "==== components ====";
const TEXT: &str = "==== licence text ";

/// One component (a crate, or material like the Lucide icons).
#[derive(Debug, Clone, PartialEq)]
pub struct Component<'a> {
    pub name: &'a str,
    pub version: &'a str,
    /// The SPDX licence expression.
    pub licence: &'a str,
    /// The binaries containing it, each with the platforms (`std::env::consts::OS`
    /// names) — empty: all.
    used: Vec<(&'a str, Vec<&'a str>)>,
    /// Its licence texts (indices into [`List::texts`]).
    pub texts: Vec<usize>,
    /// E.g. "no licence file in the package: standard MIT text; copyright: …".
    pub note: &'a str,
}

impl Component<'_> {
    /// Compiled into `app` on `os`.
    pub fn in_app(&self, app: &str, os: &str) -> bool {
        self.used
            .iter()
            .any(|(bin, oses)| *bin == app && (oses.is_empty() || oses.contains(&os)))
    }

    /// The licence ids its expression names (`Apache-2.0 WITH LLVM-exception` counts as
    /// Apache-2.0).
    pub fn licence_ids(&self) -> BTreeSet<&str> {
        let mut ids = BTreeSet::new();
        let mut after_with = false;
        for w in self
            .licence
            .split(|c: char| c.is_whitespace() || c == '(' || c == ')')
        {
            match w {
                "" => {}
                "OR" | "AND" => {}
                "WITH" => after_with = true,
                _ if after_with => after_with = false,
                id => {
                    ids.insert(id.trim_end_matches('+'));
                }
            }
        }
        ids
    }
}

/// The parsed list.
#[derive(Debug, Default)]
pub struct List<'a> {
    pub components: Vec<Component<'a>>,
    /// Licence text `n` is `texts[n - 1]`.
    pub texts: Vec<&'a str>,
}

/// Parses the generated list (see `crates/xtask/src/licenses.rs` for its format).
pub fn parse(list: &str) -> List<'_> {
    let mut out = List::default();
    let Some(start) = list.find(COMPONENTS) else {
        return out;
    };
    let body = &list[start + COMPONENTS.len()..];
    let (rows, texts) = match body.find(&format!("\n{TEXT}")) {
        Some(i) => (&body[..i], &body[i + 1..]),
        None => (body, ""),
    };
    for line in rows.lines() {
        if line.starts_with('#') || line.trim().is_empty() {
            continue;
        }
        let f: Vec<&str> = line.split(" | ").map(str::trim).collect();
        if f.len() < 5 {
            continue;
        }
        let used = f[3]
            .split_whitespace()
            .map(|u| match u.split_once('[') {
                Some((bin, oses)) => (bin, oses.trim_end_matches(']').split(',').collect()),
                None => (u, Vec::new()),
            })
            .collect();
        out.components.push(Component {
            name: f[0],
            version: f[1],
            licence: f[2],
            used,
            texts: f[4]
                .split_whitespace()
                .filter_map(|n| n.parse::<usize>().ok()?.checked_sub(1))
                .collect(),
            note: f.get(5).copied().unwrap_or(""),
        });
    }
    // "==== licence text N ====\n<text>\n\n==== licence text N+1 ====…", in order.
    for part in texts.split(&format!("\n{TEXT}")) {
        let part = part.strip_prefix(TEXT).unwrap_or(part);
        let text = part.split_once('\n').map_or("", |(_, t)| t);
        out.texts.push(text.trim_end_matches('\n'));
    }
    out
}

/// "macOS" for `std::env::consts::OS` "macos".
pub fn os_name(os: &str) -> &str {
    match os {
        "macos" => "macOS",
        "linux" => "Linux",
        "windows" => "Windows",
        other => other,
    }
}

impl<'a> List<'a> {
    /// The components compiled into `app` on `os`.
    pub fn for_app(&self, app: &str, os: &str) -> Vec<&Component<'a>> {
        self.components
            .iter()
            .filter(|c| c.in_app(app, os))
            .collect()
    }

    /// "N open-source components under MIT (…), Apache-2.0 (…), …" for `app` on `os`.
    pub fn summary(&self, app: &str, os: &str) -> String {
        let comps = self.for_app(app, os);
        let mut counts: BTreeMap<&str, usize> = BTreeMap::new();
        for c in &comps {
            for id in c.licence_ids() {
                *counts.entry(id).or_default() += 1;
            }
        }
        let mut counts: Vec<_> = counts.into_iter().collect();
        counts.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(b.0)));
        let list = counts
            .iter()
            .map(|(id, n)| format!("{id} ({n})"))
            .collect::<Vec<_>>()
            .join(", ");
        format!(
            "{app} on {} contains {} open-source components under {list} — a component \
             offered under a choice of licences counts for each.",
            os_name(os),
            comps.len()
        )
    }

    /// The whole list for `app` on `os`: its components, then their licence texts (each
    /// once, numbered anew).
    pub fn text(&self, app: &str, os: &str) -> String {
        let comps = self.for_app(app, os);
        // Texts in order of first use, renumbered from 1.
        let mut number: BTreeMap<usize, usize> = BTreeMap::new();
        let mut order: Vec<usize> = Vec::new();
        for c in &comps {
            for &t in &c.texts {
                number.entry(t).or_insert_with(|| {
                    order.push(t);
                    order.len()
                });
            }
        }
        let mut out = format!(
            "Third-party licences of {app} on {}\n\n{}\n\nEach component is listed with its \
             version and licence; [n] are its licence texts, which follow the list. The list \
             for both apps and all platforms is {LIST_PATH} in the source repository \
             ({}) and in the release packages.\n\nComponents\n",
            os_name(os),
            self.summary(app, os),
            crate::about::REPOSITORY,
        );
        for c in &comps {
            let refs = c
                .texts
                .iter()
                .map(|t| format!("[{}]", number[t]))
                .collect::<Vec<_>>()
                .join(" ");
            let version = if c.version == "-" {
                String::new()
            } else {
                format!(" {}", c.version)
            };
            let _ = writeln!(out, "  {}{version} — {} {refs}", c.name, c.licence);
            if !c.note.is_empty() {
                let _ = writeln!(out, "      {}", c.note);
            }
        }
        out.push_str("\nLicence texts\n");
        for (i, &t) in order.iter().enumerate() {
            let users = comps
                .iter()
                .filter(|c| c.texts.contains(&t))
                .map(|c| c.name)
                .collect::<BTreeSet<_>>()
                .into_iter()
                .collect::<Vec<_>>()
                .join(", ");
            let _ = write!(
                out,
                "\n[{}] used by {users}\n\n{}\n",
                i + 1,
                self.texts.get(t).copied().unwrap_or("")
            );
        }
        out
    }
}

/// The embedded list, parsed once.
pub fn list() -> &'static List<'static> {
    static LIST_PARSED: std::sync::OnceLock<List<'static>> = std::sync::OnceLock::new();
    LIST_PARSED.get_or_init(|| parse(LIST))
}

/// The whole list for `app` on this platform (Third-Party Licences…, `gitty --licenses`).
pub fn text(app: &str) -> String {
    list().text(app, std::env::consts::OS)
}

/// About's summary line for `app` on this platform.
pub fn summary(app: &str) -> String {
    list().summary(app, std::env::consts::OS)
}

#[cfg(test)]
mod tests {
    use super::*;

    const SAMPLE: &str = "Third-party licences of gitti and gitty\n\
        Cargo.lock fingerprint: 0\n\n\
        ==== components ====\n\
        # name | version | licence | used in | licence texts | note\n\
        aho-corasick  | 1.1.5 | Unlicense OR MIT | gitti gitty | 1 2\n\
        accesskit_macos | 0.26.3 | MIT OR Apache-2.0 | gitti[macos] | 2 | no licence file\n\
        wasi | 0.11 | Apache-2.0 WITH LLVM-exception OR Apache-2.0 OR MIT | gitty[linux,windows] | 3\n\
        Lucide icons | - | ISC AND MIT | gitti | 4\n\
        \n==== licence text 1 ====\nUNLICENSE\n\
        \n==== licence text 2 ====\nMIT\n  text\n\
        \n==== licence text 3 ====\nAPACHE\n\
        \n==== licence text 4 ====\nISC\n";

    #[gitti_test::test]
    fn parses_and_filters_by_app_and_platform() {
        let l = parse(SAMPLE);
        assert_eq!(l.components.len(), 4);
        assert_eq!(l.texts, vec!["UNLICENSE", "MIT\n  text", "APACHE", "ISC"]);
        let names = |app, os| {
            l.for_app(app, os)
                .iter()
                .map(|c| c.name)
                .collect::<Vec<_>>()
        };
        assert_eq!(
            names("gitti", "macos"),
            ["aho-corasick", "accesskit_macos", "Lucide icons"]
        );
        assert_eq!(names("gitti", "linux"), ["aho-corasick", "Lucide icons"]);
        assert_eq!(names("gitty", "linux"), ["aho-corasick", "wasi"]);
        assert_eq!(names("gitty", "macos"), ["aho-corasick"]);
        assert_eq!(l.components[1].note, "no licence file");
        assert_eq!(
            l.components[2]
                .licence_ids()
                .into_iter()
                .collect::<Vec<_>>(),
            ["Apache-2.0", "MIT"]
        );
    }

    #[gitti_test::test]
    fn summary_counts_each_licence_of_a_choice() {
        let l = parse(SAMPLE);
        assert_eq!(
            l.summary("gitti", "macos"),
            "gitti on macOS contains 3 open-source components under MIT (3), Apache-2.0 (1), \
             ISC (1), Unlicense (1) — a component offered under a choice of licences counts \
             for each."
        );
    }

    #[gitti_test::test]
    fn text_lists_own_components_and_each_text_once() {
        let t = parse(SAMPLE).text("gitti", "linux");
        assert!(
            t.starts_with("Third-party licences of gitti on Linux\n\ngitti on Linux contains 2"),
            "{t}"
        );
        assert!(
            t.contains("\n  aho-corasick 1.1.5 — Unlicense OR MIT [1] [2]\n"),
            "{t}"
        );
        assert!(t.contains("\n  Lucide icons — ISC AND MIT [3]\n"), "{t}");
        assert!(!t.contains("accesskit") && !t.contains("APACHE"), "{t}");
        assert!(
            t.contains("\n[2] used by aho-corasick\n\nMIT\n  text\n"),
            "{t}"
        );
        assert!(t.ends_with("\n[3] used by Lucide icons\n\nISC\n"), "{t}");
    }

    /// The embedded list parses: every component has its texts, both apps have components
    /// on every platform, and the icons are in gitti.
    #[gitti_test::test]
    fn embedded_list_is_complete() {
        let l = list();
        assert!(l.components.len() > 300, "{}", l.components.len());
        for c in &l.components {
            assert!(!c.texts.is_empty(), "{} has no licence text", c.name);
            for &t in &c.texts {
                assert!(
                    l.texts.get(t).is_some_and(|t| !t.is_empty()),
                    "{} text {t}",
                    c.name
                );
            }
        }
        for os in ["macos", "linux", "windows"] {
            assert!(l.for_app("gitti", os).len() > 300, "gitti {os}");
            assert!(l.for_app("gitty", os).len() > 100, "gitty {os}");
            assert!(
                l.for_app("gitti", os)
                    .iter()
                    .any(|c| c.name == "Lucide icons")
            );
            assert!(l.for_app("gitty", os).iter().any(|c| c.name == "ratatui"));
            assert!(
                !l.for_app("gitty", os)
                    .iter()
                    .any(|c| c.name.starts_with("gpui"))
            );
        }
    }
}
